# Generated by Claude (Claude Code).
"""Random functions on [0, 1] with exactly 0, 1 or 2 peaks.

A peak is an interior local maximum: the edges x = 0 and x = 1 never count, and
valleys (local minima) don't count either.

Each function is built from knots: x = 0, the interior extrema (peaks P and
valleys V) at sorted uniform random positions, and x = 1. Neighbouring knots are
connected with a smoothstep curve, which is strictly monotone between knots and
has zero slope at every knot, so the function has exactly the intended extrema.

Knot values come from three bands, which keeps every extremum consistent:
peaks ~ U[2/3, 1], edges ~ U[1/3, 2/3], valleys ~ U[0, 1/3].

Each function is then warped: the result is post(f(pre(x))), where pre and post are
random strictly increasing maps of [0, 1] onto itself, drawn independently per function.
They keep every peak and valley, so the label stays correct. WARP selects the family:

- "cubic" (default): the cubic w with w(0) = 0, w(1) = 1, w'(0) = alpha, w'(1) = beta,
  i.e. w(x) = (alpha + beta - 2) x^3 + (3 - 2 alpha - beta) x^2 + alpha x. It is monotone
  exactly when alpha, beta >= 0 and alpha + beta - sqrt(alpha * beta) <= 3; (alpha, beta)
  is drawn uniformly from that region (area 6 + 4 pi / sqrt(3)), without rejection: the
  region is the kite (0,0), (3,0), (2,2), (0,3) plus the sector of the ellipse
  (alpha-2)^2 + (alpha-2)(beta-2) + (beta-2)^2 <= 3 around (2, 2) beyond the kite.
  Where w' touches 0, it does so at isolated points, so w is still strictly increasing.
- "quadratic" (used by all runs before 2026-11-25): w(x) = x * (c * (x - 1) + 1) with
  c ~ U[-1, 1], the special case alpha = 1 - c, beta = 1 + c.
- "shavgulidze": a sample of the Shavgulidze measure on the increasing diffeomorphisms of
  [0, 1], the image of the Wiener measure under xi -> w(x) = int_0^x e^xi / int_0^1 e^xi, with
  xi a Brownian motion (xi(0) = 0, variance SHAVGULIDZE_SIGMA^2 t). xi is drawn from its
  Karhunen-Loeve expansion xi(t) = sum_k c_k sqrt(2) sin((k - 1/2) pi t) / ((k - 1/2) pi),
  c_k = sigma * Z_k with Z_k standard normal, truncated to SHAVGULIDZE_TERMS terms (64 keep
  99.4% of the path's variance). w is integrated with the trapezoidal rule on SHAVGULIDZE_GRID
  intervals and interpolated linearly, so it is strictly increasing with w(0) = 0, w(1) = 1.

Neighbouring knots (the edges included) keep a horizontal and a vertical distance of at
least MIN_KNOT_DISTANCE (before warping), drawn without rejection: the distribution is the
uniform one above conditioned on these distances, i.e. exactly what rejection sampling would
give. Horizontally, k sorted uniform points in [0, 1 - (k+1) d] are shifted by d, 2d, ..., kd.
Vertically, peak and valley bands are 1/3 apart, so only pairs with an edge can be too close:
two edges (monotone pattern) are drawn by sort-and-shift; an edge next to a peak from the band
rectangle minus its forbidden corner; for patterns P and V (both edges next to the same knot)
the knot comes from its exact marginal and both edges from their allowed interval. Valleys
reuse the peak samplers mirrored at y = 1/2. With MIN_KNOT_DISTANCE = 0, the generator
reproduces the functions of all runs before 2026-11-25 (no minimum distance).

The warping can still squeeze knots together, so a peak can occasionally be invisible on the
sample grid; the label is still the intended class.
"""

from typing import NamedTuple

import numpy as np

NUM_CLASSES = 3

# Family of the random warps applied before and after the knot curve: "cubic", "quadratic" or
# "shavgulidze".
WARP = "cubic"
SHAVGULIDZE_SIGMA = 1.0   # standard deviation of the Brownian motion at t = 1
SHAVGULIDZE_TERMS = 64    # Karhunen-Loeve terms of the Brownian motion
SHAVGULIDZE_GRID = 2048   # trapezoidal intervals for the integral of e^xi
# numbers per warp: (c,), (alpha, beta) or the Karhunen-Loeve coefficients (c_1, ..., c_K)
WARP_PARAMS = {"quadratic": 1, "cubic": 2, "shavgulidze": SHAVGULIDZE_TERMS}

# Minimum horizontal and vertical distance of neighbouring knots, edges included (0 = none).
MIN_KNOT_DISTANCE = 0.05

# Areas of the pieces of the admissible (alpha, beta) region of the cubic warp.
KITE_HALF_AREA = 3.0                      # triangles (0,0),(3,0),(2,2) and (0,0),(2,2),(0,3)
SECTOR_AREA = 4.0 * np.pi / np.sqrt(3.0)  # elliptic sector around (2, 2)
CUBIC_REGION_AREA = 2.0 * KITE_HALF_AREA + SECTOR_AREA

# Interior extrema patterns per class; a pattern is chosen uniformly within the class.
PATTERNS = {
    0: ["", "V"],
    1: ["P", "VP", "PV", "VPV"],
    2: ["PVP", "VPVP", "PVPV", "VPVPV"],
}

PEAK_BAND = (2 / 3, 1.0)
EDGE_BAND = (1 / 3, 2 / 3)
VALLEY_BAND = (0.0, 1 / 3)


def smoothstep(t: np.ndarray) -> np.ndarray:
    return t * t * (3.0 - 2.0 * t)


_KL_CACHE: dict = {}


def _kl_basis(terms: int, grid: int) -> tuple[np.ndarray, np.ndarray]:
    """Grid t (grid + 1 points) and the Karhunen-Loeve basis sqrt(2) sin((k-1/2) pi t)/((k-1/2) pi)."""
    if (terms, grid) not in _KL_CACHE:
        t = np.linspace(0.0, 1.0, grid + 1)
        freq = (np.arange(1, terms + 1) - 0.5) * np.pi
        _KL_CACHE[terms, grid] = t, np.sqrt(2.0) * np.sin(np.outer(t, freq)) / freq
    return _KL_CACHE[terms, grid]


def shavgulidze_grid(coefficients) -> tuple[np.ndarray, np.ndarray]:
    """The Shavgulidze warp with the given Karhunen-Loeve coefficients on its integration grid:
    (t, w(t)), w normalized to w(0) = 0, w(1) = 1."""
    t, basis = _kl_basis(len(coefficients), SHAVGULIDZE_GRID)
    xi = basis @ np.asarray(coefficients, dtype=np.float64)
    e = np.exp(xi - xi.max())  # the normalization cancels the shift; avoids overflow
    w = np.concatenate(([0.0], np.cumsum((e[1:] + e[:-1]) / 2.0)))
    return t, w / w[-1]


def warp(x: np.ndarray, params: tuple[float, ...]) -> np.ndarray:
    """Apply a warp of [0, 1]: params = (c,) for the quadratic warp x * (c * (x - 1) + 1),
    (alpha, beta) for the cubic warp with slopes alpha at 0 and beta at 1, or more numbers for
    a Shavgulidze warp (its Karhunen-Loeve coefficients)."""
    if len(params) > 2:
        t, w = shavgulidze_grid(params)
        return np.interp(x, t, w)
    if len(params) == 1:
        (c,) = params
        return x * (c * (x - 1.0) + 1.0)
    alpha, beta = params
    a, b = alpha + beta - 2.0, 3.0 - 2.0 * alpha - beta
    return x * (alpha + x * (b + x * a))


def sample_cubic_warp(rng: np.random.Generator) -> tuple[float, float]:
    """(alpha, beta) uniform on the region where the cubic warp is monotone, from 3 uniform numbers.

    The first number picks a piece with probability proportional to its area; the other two
    give a uniform point in it: triangles via reflection into the unit triangle, the sector via
    a uniform point of a disk sector mapped affinely onto the ellipse."""
    u0, u1, u2 = rng.random(3)
    pick = u0 * CUBIC_REGION_AREA
    if pick < 2.0 * KITE_HALF_AREA:
        if u1 + u2 > 1.0:
            u1, u2 = 1.0 - u1, 1.0 - u2
        if pick < KITE_HALF_AREA:  # triangle (0,0), (3,0), (2,2)
            return 3.0 * u1 + 2.0 * u2, 2.0 * u2
        return 2.0 * u1, 2.0 * u1 + 3.0 * u2  # triangle (0,0), (2,2), (0,3)
    theta = (4.0 * u1 - 2.0) * np.pi / 3.0  # [-2 pi / 3, 2 pi / 3]
    r = np.sqrt(u2)
    return 2.0 + 2.0 * r * np.cos(theta - np.pi / 3.0), 2.0 + 2.0 * r * np.cos(theta + np.pi / 3.0)


def sample_warp(rng: np.random.Generator) -> tuple[float, ...]:
    """Parameters of one random warp of the family WARP."""
    if WARP == "quadratic":
        return (float(rng.uniform(-1.0, 1.0)),)
    if WARP == "cubic":
        return tuple(float(v) for v in sample_cubic_warp(rng))
    if WARP == "shavgulidze":
        return tuple(float(v) for v in SHAVGULIDZE_SIGMA * rng.standard_normal(SHAVGULIDZE_TERMS))
    raise ValueError(f"unknown WARP {WARP!r}; use 'cubic', 'quadratic' or 'shavgulidze'")


class FunctionParams(NamedTuple):
    """Random parameters of one function."""

    pattern: str        # interior extrema, e.g. "VPV"
    knot_x: np.ndarray  # sorted knot positions, including the edges 0 and 1
    knot_y: np.ndarray  # knot values
    pre: tuple          # precomposition warp: (c,) quadratic, (alpha, beta) cubic, (c_1..c_K) Shavgulidze
    post: tuple         # postcomposition warp, same form


def _edge_and_peak(d: float, rng: np.random.Generator) -> tuple[float, float]:
    """(edge, peak) uniform on EDGE_BAND x PEAK_BAND with peak - edge >= d.

    With a = 2/3 - edge and b = peak - 2/3 in [0, 1/3], the region a + b >= d is the rectangle
    a >= d plus the trapezoid a < d, b >= d - a (density of a there proportional to 1/3 - d + a)."""
    c = 1.0 / 3.0
    u0, u1, u2 = rng.random(3)
    rect, trap = (c - d) * c, d * c - d * d / 2.0
    if u0 * (rect + trap) < rect:
        a, b = d + u1 * (c - d), u2 * c
    else:
        a = -(c - d) + np.sqrt((c - d) ** 2 + 2.0 * u1 * trap)  # inverse CDF of the linear density
        b = (d - a) + u2 * (c - d + a)
    return 2.0 / 3.0 - a, 2.0 / 3.0 + b


def _peak_between_edges(d: float, rng: np.random.Generator) -> tuple[float, float, float]:
    """(edge, peak, edge) uniform on EDGE_BAND x PEAK_BAND x EDGE_BAND with both edges >= d below.

    Given the peak m, each edge is uniform on [1/3, 1/3 + L], L = min(1/3, m - d - 1/3), so m has
    density proportional to L(m)^2: with z = m - 2/3, (1/3 - d + z)^2 for z < d, else 1/9."""
    c = 1.0 / 3.0
    u0, u1, u2, u3 = rng.random(4)
    curved, flat = (c**3 - (c - d) ** 3) / 3.0, c * c * (c - d)
    if u0 * (curved + flat) < curved:
        z = np.cbrt((c - d) ** 3 + u1 * (c**3 - (c - d) ** 3)) - (c - d)  # inverse CDF of the cubic part
    else:
        z = d + u1 * (c - d)
    length = min(c, c - d + z)
    return c + u2 * length, 2.0 / 3.0 + z, c + u3 * length


def _two_edges(d: float, rng: np.random.Generator) -> tuple[float, float]:
    """Two edge values uniform on EDGE_BAND^2 with |difference| >= d (sort-and-shift, random order)."""
    lo, hi = np.sort(rng.uniform(EDGE_BAND[0], EDGE_BAND[1] - d, 2))
    pair = (lo, hi + d)
    return pair if rng.random() < 0.5 else pair[::-1]


def _knot_values(pattern: str, d: float, rng: np.random.Generator) -> np.ndarray:
    """Knot values (edges included) with vertical neighbour distances >= d, uniform given that."""
    def mirror(values, is_valley):  # y -> 1 - y turns a valley into a peak and keeps the edge band
        return tuple(1.0 - v for v in values) if is_valley else values

    k = len(pattern)
    y = np.empty(k + 2)
    if k == 0:
        y[:] = _two_edges(d, rng)
    elif k == 1:
        y[:] = mirror(_peak_between_edges(d, rng), pattern == "V")
    else:
        y[0], y[1] = mirror(_edge_and_peak(d, rng), pattern[0] == "V")
        y[-1], y[-2] = mirror(_edge_and_peak(d, rng), pattern[-1] == "V")
        for j in range(2, k):  # interior knots without an edge neighbour: their band only
            lo, hi = PEAK_BAND if pattern[j - 1] == "P" else VALLEY_BAND
            y[j] = rng.uniform(lo, hi)
    return y


def sample_params(pattern: str, rng: np.random.Generator) -> FunctionParams:
    """Draw the random parameters of one function with the given interior extrema pattern."""
    d = MIN_KNOT_DISTANCE
    k = len(pattern)
    if not 0.0 <= d < 1.0 / 6.0:  # 6 gaps for the longest pattern; edge pairs need d < 1/3
        raise ValueError(f"MIN_KNOT_DISTANCE must be in [0, 1/6), got {d}")
    if d == 0.0:  # the original sampling, draw for draw
        interior_x = np.sort(rng.uniform(0.0, 1.0, k))
        knot_x = np.concatenate(([0.0], interior_x, [1.0]))
        bands = [EDGE_BAND] + [PEAK_BAND if c == "P" else VALLEY_BAND for c in pattern] + [EDGE_BAND]
        knot_y = np.array([rng.uniform(lo, hi) for lo, hi in bands])
    else:
        interior_x = np.sort(rng.uniform(0.0, 1.0 - (k + 1) * d, k)) + d * np.arange(1, k + 1)
        knot_x = np.concatenate(([0.0], interior_x, [1.0]))
        knot_y = _knot_values(pattern, d, rng)

    if WARP == "quadratic":  # both parameters in one call, as in all runs before the cubic warp
        g, h = rng.uniform(-1.0, 1.0, 2)
        pre, post = (float(g),), (float(h),)
    else:
        pre, post = sample_warp(rng), sample_warp(rng)
    return FunctionParams(pattern, knot_x, knot_y, pre, post)


def evaluate_params(params: FunctionParams, x: np.ndarray) -> np.ndarray:
    """Values post(f(pre(x))) of the function with the given parameters at the points x."""
    knot_x, knot_y = params.knot_x, params.knot_y
    u = warp(x, params.pre)  # precompose: evaluate the knot curve at pre(x)

    # Segment index i such that knot_x[i] <= u <= knot_x[i + 1].
    i = np.clip(np.searchsorted(knot_x, u, side="right") - 1, 0, len(knot_x) - 2)
    t = (u - knot_x[i]) / (knot_x[i + 1] - knot_x[i])
    f = knot_y[i] + (knot_y[i + 1] - knot_y[i]) * smoothstep(t)
    return warp(f, params.post)  # postcompose


def make_function(pattern: str, x: np.ndarray, rng: np.random.Generator) -> np.ndarray:
    """Sample one function with the given interior extrema pattern at the points x."""
    return evaluate_params(sample_params(pattern, rng), x)


def generate_batch(
    batch_size: int, num_samples: int, rng: np.random.Generator
) -> tuple[np.ndarray, np.ndarray]:
    """Return (functions, labels).

    functions: float32 array (batch_size, num_samples), values at evenly spaced x in [0, 1].
    labels:    int64 array (batch_size,), the number of peaks (each class equally likely).
    """
    x = np.linspace(0.0, 1.0, num_samples)
    labels = rng.integers(0, NUM_CLASSES, batch_size)
    functions = np.empty((batch_size, num_samples), dtype=np.float32)
    for n, label in enumerate(labels):
        patterns = PATTERNS[label]
        pattern = patterns[rng.integers(len(patterns))]
        functions[n] = make_function(pattern, x, rng)
    return functions, labels.astype(np.int64)
